543				return
544			default:
545				writeError(w, http.StatusInternalServerError, "failed to restore snapshot")
546				return
547			}
548		}
549	
550		writeJSON(w, http.StatusOK, result)
551	}
552	
553	// handleSetPermission grants or revokes a registered device's access to one
554	// document. Devices start authorized, so the first revoke is the first write;
555	// repeating the current state is idempotent (changed=false). A rejected
556	// request (bad content type, malformed JSON, trailing content, empty or
557	// mistyped fields, unknown action) is a 400 JSON error and writes nothing; an
558	// unregistered device is a 404 JSON error.
559	func handleSetPermission(s *store.Store, w http.ResponseWriter, r *http.Request) {
560		documentID := r.PathValue("documentID") // route pattern guarantees non-empty
561	
562		var req permissionRequest
563		if !decodeJSONBody(w, r, &req) {
564			return
565		}
566		if req.DeviceID == "" {
567			writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
568			return
569		}
570		var authorized bool
571		switch req.Action {
572		case "grant":
573			authorized = true
574		case "revoke":
575			authorized = false
576		default:
577			writeError(w, http.StatusBadRequest, `action must be "grant" or "revoke"`)
578			return
579		}
580	
581		changed, err := s.SetDocumentPermission(documentID, req.DeviceID, authorized)
582		if err != nil {
583			if errors.Is(err, store.ErrDeviceNotFound) {
584				writeError(w, http.StatusNotFound, "device not found")
585				return
586			}
587			writeError(w, http.StatusInternalServerError, "failed to update permission")
588			return
589		}
590	
591		writeJSON(w, http.StatusOK, map[string]any{
592			"deviceId":   req.DeviceID,
593			"authorized": authorized,
594			"changed":    changed,
595		})
596	}
597	
598	// parseCursorPath reports whether raw is a decimal non-negative integer and
599	// returns its value. Signs, fractions and other adornments are rejected.
600	func parseCursorPath(raw string) (int64, bool) {
601		if raw == "" {
602			return 0, false
603		}
604		for _, c := range raw {
605			if c < '0' || c > '9' {
606				return 0, false
607			}
608		}
609		n, err := strconv.ParseInt(raw, 10, 64)
610		if err != nil {
611			return 0, false
612		}
613		return n, true
614	}
615	
616	// parseNonNegativeInt reports whether raw is a JSON integer >= 0. Floats,// strings, booleans, null and negative numbers are rejected.
617	func parseNonNegativeInt(raw json.RawMessage) (int64, bool) {
618		var n int64
619		if err := json.Unmarshal(raw, &n); err != nil || n < 0 {
620			return 0, false
621		}
622		// Guard against values like 1.0 that Unmarshal into int64 on some inputs;
623		// require the literal to contain no fraction or exponent.
624		trimmed := strings.TrimSpace(string(raw))
625		if trimmed == "" || trimmed[0] == '-' {
626			return 0, false
627		}
628		for _, c := range trimmed {
629			if c < '0' || c > '9' {
630				return 0, false
631			}
632		}
633		return n, true
634	}
635	
636	// parsePositiveInt reports whether raw is a JSON integer >= 1. Zero, floats,
637	// strings, booleans, null and negative numbers are rejected.
638	func parsePositiveInt(raw json.RawMessage) (int64, bool) {
639		n, ok := parseNonNegativeInt(raw)
640		if !ok || n < 1 {
641			return 0, false
642		}
643		return n, true
644	}
645	
646	// isJSONObject reports whether raw decodes to a JSON object (not null, an
647	// array or a scalar).
648	func isJSONObject(raw json.RawMessage) bool {
649		var m map[string]json.RawMessage
650		if err := json.Unmarshal(raw, &m); err != nil || m == nil {
651			return false
652		}
653		return true
654	}
655	
656	func handleListChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
657		documentID := r.PathValue("documentID")
658	
659		after, limit, ok := parseChangesQuery(w, r)
660		if !ok {
661			return
662		}
663	
664		changes, nextCursor, err := s.ListChanges(documentID, after, limit)
665		if err != nil {
666			writeError(w, http.StatusInternalServerError, "failed to list changes")
667			return
668		}
669	
670		writeChangesPage(w, changes, nextCursor)
671	}
672	
673	// handleSessionChanges is the session-scoped view of the existing change log:
674	// both path identifiers must be non-empty (the empty-segment guard rejects
675	// those before routing) and the session must currently exist, after which the
676	// query behaves exactly like GET /v1/documents/{documentID}/changes — unless
677	// the session's device has been revoked permission for the document, which is
678	// a 403 JSON error with no changes or nextCursor. Revocation only gates this
679	// read; the change log itself is untouched.
680	func handleSessionChanges(s *store.Store, w http.ResponseWriter, r *http.Request) {
681		sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
682		documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty
683	
684		// Malformed query parameters are a request-shape error (400) checked
685		// before the resource lookup (404), matching the snapshot GET ordering.
686		after, limit, ok := parseChangesQuery(w, r)
687		if !ok {
688			return
689		}
690	
691		deviceID, err := s.SessionDevice(sessionID)
692		if err != nil {
693			if errors.Is(err, store.ErrSessionNotFound) {
694				writeError(w, http.StatusNotFound, "session not found")
695				return
696			}
697			writeError(w, http.StatusInternalServerError, "failed to look up session")
698			return
699		}
700	
701		authorized, err := s.DocumentAuthorized(documentID, deviceID)
702		if err != nil {
703			writeError(w, http.StatusInternalServerError, "failed to look up permission")
704			return
705		}
706		if !authorized {
707			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
708			return
709		}
710	
711		changes, nextCursor, err := s.ListChanges(documentID, after, limit)
712		if err != nil {
713			writeError(w, http.StatusInternalServerError, "failed to list changes")
714			return
715		}
716	
717		writeChangesPage(w, changes, nextCursor)
718	}
719	
720	// parseChangesQuery parses the shared after/limit pagination parameters,
721	// writing the documented 400 on an illegal value. It is shared by the
722	// document-scoped and session-scoped change listings so their query semantics
723	// cannot drift apart.
724	func parseChangesQuery(w http.ResponseWriter, r *http.Request) (after, limit int64, ok bool) {
725		q := r.URL.Query()
726	
727		after = 0
728		if raw := q.Get("after"); raw != "" {
729			v, err := strconv.ParseInt(raw, 10, 64)
730			if err != nil || v < 0 {
731				writeError(w, http.StatusBadRequest, "after must be a non-negative integer")
732				return 0, 0, false
733			}
734			after = v
735		}
736	
737		limit = defaultListLimit
738		if raw := q.Get("limit"); raw != "" {
739			v, err := strconv.ParseInt(raw, 10, 64)
740			if err != nil || v < 1 || v > maxListLimit {
741				writeError(w, http.StatusBadRequest, "limit must be an integer between 1 and 1000")
742				return 0, 0, false
743			}
744			limit = v
745		}
746	
747		return after, limit, true
748	}
749	
750	// writeChangesPage renders a change listing page in the shared response shape.
751	func writeChangesPage(w http.ResponseWriter, changes []store.ListedChange, nextCursor int64) {
752		writeJSON(w, http.StatusOK, map[string]any{
753			"changes":    changes,
754			"nextCursor": nextCursor,
755		})
756	}
757	
758	func writeJSON(w http.ResponseWriter, status int, v any) {
759		w.Header().Set("Content-Type", "application/json")
760		w.WriteHeader(status)
761		_ = json.NewEncoder(w).Encode(v)
762	}
763	
764	func writeError(w http.ResponseWriter, status int, message string) {
765		writeJSON(w, status, map[string]string{"error": message})
766	}
767

