257	// toAttachment builds the create-time metadata for content with the given
258	// chunking.
259	func toAttachment(id string, total, chunk int64, content []byte) Attachment {
260		return Attachment{
261			ID:         id,
262			TotalBytes: total,
263			ChunkSize:  chunk,
264			SHA256:     digestOf(content),
265		}
266	}
